const extraNews=[
  {id:"team",type:"news",category:"Новости",date:"07.11.2026",title:"Как собрать команду для инженерного проекта",excerpt:"Роли, ответственность и общий язык внутри команды",art:"news-team",body:["Сильная команда начинается с понятной задачи. Прежде чем искать участников, автору полезно сформулировать, какую часть решения уже можно показать и какой компетенции пока не хватает.","В заявке стоит указать вклад каждого человека: кто отвечает за механику, программирование, визуальную часть, испытания и презентацию. Это помогает экспертам увидеть реальную работу команды.","Если над проектом трудятся участники из разных городов, договоритесь о едином месте хранения схем и материалов. Перед подачей проверьте, что у команды есть право использовать все приложенные изображения, тексты и видео."]},
  {id:"materials",type:"news",category:"Новости",date:"05.11.2026",title:"Какие материалы помогут показать решение",excerpt:"Схема, фотографии и короткое видео делают заявку понятнее",art:"news-materials",body:["Эксперт должен быстро понять, что делает проект и чем подтверждается его работоспособность. Начните с одной схемы, на которой видны основные узлы и связи между ними.","Добавьте несколько изображений прототипа или макета. Если движение важно для идеи, короткое видео покажет больше, чем длинное описание. Подписи должны объяснять, что именно изображено.","Не перегружайте заявку файлами. Лучше выбрать материалы, которые подтверждают актуальность задачи, проработку решения и возможность применения."]},
  {id:"safety",type:"news",category:"Новости",date:"03.11.2026",title:"Безопасная демонстрация проекта",excerpt:"Что проверить до показа устройства зрителям",art:"news-safety",body:["Интерактивное устройство работает рядом с людьми, поэтому безопасность нужно продумать на этапе макета. Команда описывает, какие части движутся, как ограничена зона работы и что происходит при остановке питания.","Для показа на фестивале важны устойчивое крепление, понятный сценарий запуска и человек, который отвечает за работу устройства. Эти условия стоит отразить в заявке.","Даже если проект существует только как концепция, полезно назвать основные риски и способ их проверить. Такой подход показывает экспертам, что команда понимает путь от идеи до применения."]},
  {id:"cities",type:"news",category:"Новости",date:"01.11.2026",title:"Что увидят посетители фестивалей",excerpt:"Демонстрации, встречи с авторами и разговоры о применении",art:"news-cities",body:["Фестивальная программа помогает проектам выйти за пределы заявки. Посетители смогут увидеть инженерные решения в действии и задать вопросы командам.","Для авторов это шанс проверить, понятна ли идея человеку, который раньше о ней не слышал. Обратная связь зрителей может подсказать новые сценарии использования.","Отдельные встречи будут посвящены тому, как решения проходят путь от макета к реальной площадке. Подробности по каждому городу размещаются в разделе фестивалей."]},
  {id:"dialogue",type:"news",category:"Новости",date:"26.10.2026",title:"Зачем проектам разговор с партнерами",excerpt:"Внешний взгляд помогает выбрать следующий шаг разработки",art:"news-dialogue",body:["Инженерная команда часто хорошо знает устройство своего решения, но ей бывает трудно оценить условия реального применения. Разговор с партнером помогает проверить ограничения площадки, обслуживания и бюджета.","На встрече полезно показать не только итоговую идею, но и результаты проверок: что уже работает, что еще требует испытаний, какие ресурсы нужны для следующей версии.","Партнерский интерес не означает автоматического внедрения. Он дает проекту конкретные вопросы, которые стоит проработать перед масштабированием."]},
  {id:"draft",type:"news",category:"Новости",date:"23.10.2026",title:"Черновик заявки: работа без спешки",excerpt:"Сохраните описание и вернитесь к нему перед отправкой",art:"news-draft",body:["Заявку удобно собирать по частям. Сначала зафиксируйте задачу и идею решения, затем добавьте технические детали, состав команды и материалы.","Перед отправкой прочитайте текст как новый человек: понятно ли, кто будет пользоваться проектом, что уже сделано и какое подтверждение есть у ключевых утверждений.","Проверьте названия файлов и подписи к изображениям. После отправки статус заявки появится в кабинете участника."]},
  {id:"public-card",type:"news",category:"Новости",date:"18.10.2026",title:"Публичная карточка и полная заявка",excerpt:"Какие материалы увидят зрители, а какие останутся у экспертов",art:"news-public",body:["Полная конкурсная заявка нужна для оценки. В ней могут быть схемы, расчеты, файлы испытаний и описание ограничений, которые автор не хочет размещать в открытом доступе.","Публичная карточка короче: название, идея, команда и материалы, которые автор разрешил показать. Она помогает посетителям каталога познакомиться с проектом без раскрытия внутренней документации.","Автор управляет публикацией отдельно от подачи заявки. Для несовершеннолетнего участника требуется согласие законного представителя."]}
];
