function mediaCard(item,index){return `<article class="media-card" data-media-item="news" data-media-type="news" data-media-subtype="${item.type}" data-media-search="${esc(`${item.title} ${item.excerpt} ${item.category}`.toLocaleLowerCase("ru"))}" data-item-index="${index}" ${index>=state.mediaShown.news?"hidden":""}><a class="media-card-link" href="#/media/story/${item.id}" aria-label="Открыть новость: ${esc(item.title)}"><div class="media-card-art">${geometricArt(item.art)}</div><div class="media-card-copy"><div class="media-meta"><span>${esc(item.category)}</span><time>${item.date}</time></div><h3>${esc(item.title)}</h3><p>${esc(item.excerpt)}</p><span class="media-card-action">Читать новость ${icon("arrow")}</span></div></a></article>`}
function pressCard(item,index){return `<article class="media-press-card" data-media-item="press" data-media-type="press" data-media-search="${esc(`${item.outlet} ${item.title} ${item.description}`.toLocaleLowerCase("ru"))}" data-item-index="${index}" ${index>=state.mediaShown.press?"hidden":""}><a href="${esc(item.url)}" target="_blank" rel="noopener noreferrer"><span class="media-press-outlet">${esc(item.outlet)}</span><h3>${esc(item.title)}</h3><p>${esc(item.description)}</p><span class="media-press-action">Читать в издании ${icon("arrow")}</span></a></article>`}
function mediaAssetCard(item,index){const photo=item.kind==="photo",action=photo?`data-photo-archive="${item.id}"`:`data-video-id="${item.id}"`;return `<article class="media-asset-card" data-media-item="assets" data-media-type="${item.kind}" data-media-search="${esc(`${item.title} ${item.description}`.toLocaleLowerCase("ru"))}" data-item-index="${index}" ${index>=state.mediaShown.assets?"hidden":""}><button type="button" ${action} aria-label="${photo?"Открыть фотоархив":"Открыть видео"}: ${esc(item.title)}"><div class="media-asset-art">${geometricArt(photo?item.frames[0][1]:item.art)}<span class="media-asset-kind">${photo?"Фотоархив":"Видео"}</span><span class="media-asset-play">${icon(photo?"image":"play")}</span></div><div class="media-asset-copy"><h3>${esc(item.title)}</h3><p>${esc(item.description)}</p><span>${photo?`${item.frames.length} кадра · Открыть галерею`:"Смотреть видео"} ${icon("arrow")}</span></div></button></article>`}
function media(){const filters=[["all","Все"],["news","Новости"],["material","Материалы"],["story","Истории проектов"],["festival","Фестивали"],["press","Публикации"],["photo","Фото"],["video","Видео"]],assets=photoArchives.flatMap((photo,i)=>[{...photo,kind:"photo"},{...videoAssets[i],kind:"video"}]),featured=newsItems.find(item=>item.id==="launch");return publicShell("media",`
<section class="section media-hero media-feature-hero"><div class="wrap media-hero-layout"><div><div class="eyebrow">Новости и медиа</div><div class="media-meta media-hero-meta"><span>Главное сейчас</span><time>${featured.date}</time></div><h1>${featured.title}</h1><p class="page-lead">${featured.excerpt}. Узнайте, кто может участвовать и как подготовить проект к подаче</p><div class="actions"><a class="btn btn-primary" href="#/media/story/${featured.id}">Читать новость ${icon("arrow")}</a></div></div><div class="media-hero-art">${geometricArt(featured.art,true)}</div></div></section>
<section class="section media-archive-section" id="media-materials"><div class="wrap"><div class="eyebrow">Архив проекта</div><h2 class="media-archive-title">Новости, публикации и медиа</h2><div class="media-controls"><div class="media-filters" role="group" aria-label="Фильтр материалов">${filters.map(([id,label])=>`<button type="button" data-media-filter="${id}" aria-pressed="${state.mediaFilter===id}">${label}</button>`).join("")}</div><label class="media-search"><span class="sr-only">Поиск по материалам</span>${icon("search")}<input id="media-search" type="search" placeholder="Найти материал" autocomplete="off"></label></div><p class="media-result-count" id="media-results"></p>
<div class="media-section-group" data-media-section="news"><div class="media-section-heading"><div><div class="eyebrow">Лента проекта</div><h2>Новости</h2><p>Этапы конкурса, работа команд и события проекта</p></div><span id="media-news-count"></span></div><div class="media-grid">${newsItems.map(mediaCard).join("")}</div><button class="btn media-more" type="button" data-media-more="news">Показать еще ${icon("arrow")}</button></div>
<div class="media-section-group" data-media-section="press"><div class="media-section-heading"><div><div class="eyebrow">СМИ об инженерии</div><h2>Публикации</h2><p>Материалы сторонних изданий об инженерных конкурсах и студенческих разработках</p></div><span id="media-press-count"></span></div><div class="media-press-list">${pressItems.map(pressCard).join("")}</div><button class="btn media-more" type="button" data-media-more="press">Показать еще ${icon("arrow")}</button></div>
<div class="media-section-group" data-media-section="assets"><div class="media-section-heading"><div><div class="eyebrow">В кадре</div><h2>Фото и видео</h2><p>Фотоархивы и геометрические видео о движении, форме и свете</p></div><span id="media-assets-count"></span></div><div class="media-assets-grid">${assets.map(mediaAssetCard).join("")}</div><button class="btn media-more" type="button" data-media-more="assets">Показать еще ${icon("arrow")}</button></div><div class="media-empty" id="media-empty" hidden>По вашему запросу материалы не найдены</div></div></section>
<dialog class="media-dialog media-photo-dialog" id="media-photo-dialog" aria-label="Фотоархив"><div class="media-dialog-head"><div><span class="eyebrow">Фотоархив</span><h2 id="media-photo-title"></h2></div><button type="button" id="media-photo-close" aria-label="Закрыть">${icon("close")}</button></div><div class="media-photo-main" id="media-photo-art"></div><div class="media-photo-controls"><button type="button" id="media-photo-prev" aria-label="Предыдущий кадр">${icon("arrow")}</button><div><strong id="media-photo-caption"></strong><span id="media-photo-count"></span></div><button type="button" id="media-photo-next" aria-label="Следующий кадр">${icon("arrow")}</button></div><div class="media-photo-thumbs" id="media-photo-thumbs"></div></dialog>
<dialog class="media-dialog media-video-dialog" id="media-video-dialog" aria-label="Видеоматериал"><div class="media-dialog-head"><div><span class="eyebrow">Видео</span><h2 id="media-video-title"></h2></div><button type="button" id="media-video-close" aria-label="Закрыть">${icon("close")}</button></div><canvas id="media-video-canvas" width="960" height="540"></canvas><video id="media-video-player" controls playsinline preload="none" loop hidden></video><p class="media-video-credit" id="media-video-status" role="status"></p></dialog>`)}

function mediaStory(id){const item=newsItems.find(entry=>entry.id===id);if(!item)return media();const related=newsItems.filter(entry=>entry.id!==id).slice(0,3);const body=item.body.map((paragraph,i)=>`${i===1?`<h2>Подробности</h2>`:""}<p>${esc(paragraph)}</p>${i===1?`<figure class="media-story-inline-art">${geometricArt(`${item.art}-detail`)}<figcaption>Иллюстрация к материалу</figcaption></figure>`:""}`).join("");return publicShell("media",`
<section class="media-article-lead"><div class="wrap media-article-lead-grid"><div class="media-article-intro"><div class="eyebrow">${esc(item.category)}</div><time class="media-article-date">${item.date}</time><h1>${esc(item.title)}</h1><p class="page-lead">${esc(item.excerpt)}</p></div><figure class="media-article-cover">${geometricArt(item.art)}<figcaption class="sr-only">Геометрическая иллюстрация к публикации</figcaption></figure></div></section>
<section class="section media-story-content"><div class="wrap media-story-layout"><article class="media-story-body">${body}<div class="media-story-actions"><a class="btn" href="#/contest">Правила конкурса ${icon("arrow")}</a><button class="btn" id="media-share" type="button">Скопировать ссылку</button><span id="media-share-status" role="status"></span></div></article><aside class="media-story-aside"><div class="eyebrow">Читайте также</div>${related.map(entry=>`<a href="#/media/story/${entry.id}"><span>${esc(entry.category)} · ${entry.date}</span><strong>${esc(entry.title)}</strong>${icon("arrow")}</a>`).join("")}</aside></div></section><section class="section media-related"><div class="wrap"><div class="eyebrow">Продолжить чтение</div><h2>Другие новости</h2><div class="media-grid">${related.map((entry,i)=>mediaCard(entry,i)).join("")}</div><div class="media-story-footer"><a class="btn" href="#/media">Все новости и медиа ${icon("arrow")}</a></div></div></section>`)}
function applyMediaFilters(){if(!document.getElementById("media-materials"))return;const filter=state.mediaFilter,query=(document.getElementById("media-search")?.value||"").trim().toLocaleLowerCase("ru");let found=0;for(const kind of ["news","press","assets"]){let matching=0;document.querySelectorAll(`[data-media-item="${kind}"]`).forEach(card=>{const type=card.dataset.mediaType,subtype=card.dataset.mediaSubtype;const matches=(filter==="all"||filter===type||filter===subtype)&&(!query||card.dataset.mediaSearch.includes(query));card.hidden=!matches||matching>=state.mediaShown[kind];if(matches)matching++});document.querySelector(`[data-media-section="${kind}"]`).hidden=matching===0;document.getElementById(`media-${kind}-count`).textContent=`${matching} материалов`;const more=document.querySelector(`[data-media-more="${kind}"]`);if(more)more.hidden=matching<=state.mediaShown[kind];found+=matching}document.getElementById("media-results").textContent=`Найдено: ${found}`;document.getElementById("media-empty").hidden=found>0}
function activateMediaFilter(id){state.mediaFilter=id;state.mediaShown={news:9,press:3,assets:2};document.querySelectorAll("[data-media-filter]").forEach(button=>button.setAttribute("aria-pressed",String(button.dataset.mediaFilter===id)));applyMediaFilters()}
function loadMoreMedia(id){const total=id==="news"?newsItems.length:id==="press"?pressItems.length:photoArchives.length+videoAssets.length;state.mediaShown[id]=Math.min(total,state.mediaShown[id]+(id==="assets"?2:3));applyMediaFilters()}

let activePhotoArchive=null,activePhotoFrame=0;
function updatePhotoArchive(){if(!activePhotoArchive)return;const frames=activePhotoArchive.frames,[caption,key]=frames[activePhotoFrame];document.getElementById("media-photo-art").innerHTML=geometricArt(key);document.getElementById("media-photo-caption").textContent=caption;document.getElementById("media-photo-count").textContent=`${activePhotoFrame+1} / ${frames.length}`;const thumbs=document.getElementById("media-photo-thumbs");thumbs.innerHTML=frames.map(([label,art],i)=>`<button type="button" data-photo-frame="${i}" aria-label="Кадр ${i+1}: ${esc(label)}" aria-current="${i===activePhotoFrame}">${geometricArt(art)}</button>`).join("");thumbs.querySelectorAll("[data-photo-frame]").forEach(button=>button.addEventListener("click",()=>{activePhotoFrame=Number(button.dataset.photoFrame);updatePhotoArchive()}))}
function openPhotoArchive(id){activePhotoArchive=photoArchives.find(item=>item.id===id);if(!activePhotoArchive)return;activePhotoFrame=0;document.getElementById("media-photo-title").textContent=activePhotoArchive.title;updatePhotoArchive();document.getElementById("media-photo-dialog").showModal()}
function stepPhotoArchive(direction){if(!activePhotoArchive)return;activePhotoFrame=(activePhotoFrame+direction+activePhotoArchive.frames.length)%activePhotoArchive.frames.length;updatePhotoArchive()}
const localVideoClips=new Map();
let activeVideoRequest=0;
function drawVideoFrame(ctx,variant,progress){const w=ctx.canvas.width,h=ctx.canvas.height,t=progress*Math.PI*2;ctx.fillStyle="#f4f4f4";ctx.fillRect(0,0,w,h);ctx.strokeStyle="#525252";ctx.fillStyle="#525252";ctx.lineWidth=3;if(variant===0){for(let i=0;i<28;i++){const a=i*Math.PI/14+t;ctx.beginPath();ctx.moveTo(w/2+Math.cos(a)*72,h/2+Math.sin(a)*72);ctx.lineTo(w/2+Math.cos(a)*210,h/2+Math.sin(a)*210);ctx.stroke()}ctx.beginPath();ctx.arc(w/2,h/2,24,0,Math.PI*2);ctx.fill()}else if(variant===1){ctx.beginPath();for(let i=0;i<11;i++){const x=120+i*72,y=h/2+Math.sin(t+i*.6)*90;if(i===0)ctx.moveTo(x,y);else ctx.lineTo(x,y)}ctx.stroke();for(let i=0;i<11;i++){const x=120+i*72,y=h/2+Math.sin(t+i*.6)*90;ctx.beginPath();ctx.arc(x,y,13+i%3*5,0,Math.PI*2);ctx.fill()}}else{for(let row=0;row<6;row++)for(let col=0;col<10;col++){const x=110+col*82,y=75+row*78,size=16+15*(1+Math.sin(t+(row+col)*.48))/2;ctx.fillStyle=(row+col)%3===0?"#525252":"#a8a8a8";ctx.fillRect(x-size/2,y-size/2,size,size)}}}
function closeVideoDialog(){activeVideoRequest++;const video=document.getElementById("media-video-player");if(video){video.pause();video.removeAttribute("src");video.load();video.hidden=true}const canvas=document.getElementById("media-video-canvas");if(canvas)canvas.hidden=false}
function openVideoDialog(id){const item=videoAssets.find(entry=>entry.id===id);if(!item)return;const dialog=document.getElementById("media-video-dialog"),video=document.getElementById("media-video-player"),canvas=document.getElementById("media-video-canvas"),status=document.getElementById("media-video-status");document.getElementById("media-video-title").textContent=item.title;dialog.showModal();const request=++activeVideoRequest;const cached=localVideoClips.get(id);if(cached){canvas.hidden=true;video.hidden=false;video.src=cached;status.textContent="";video.play().catch(()=>{});return}video.hidden=true;canvas.hidden=false;status.textContent="Подготовка видео...";const ctx=canvas.getContext("2d");drawVideoFrame(ctx,item.variant,0);let recorder,stream;try{if(typeof MediaRecorder==="undefined"||!canvas.captureStream)throw new Error("recording unavailable");stream=canvas.captureStream(24);const mime=MediaRecorder.isTypeSupported("video/webm;codecs=vp8")?"video/webm;codecs=vp8":"video/webm";recorder=new MediaRecorder(stream,{mimeType:mime})}catch{status.textContent="Анимированная демонстрация";const start=performance.now();const animate=now=>{if(!dialog.open||request!==activeVideoRequest)return;drawVideoFrame(ctx,item.variant,((now-start)%4000)/4000);requestAnimationFrame(animate)};requestAnimationFrame(animate);return}const chunks=[];recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};recorder.onstop=()=>{stream.getTracks().forEach(track=>track.stop());if(!chunks.length)return;const url=URL.createObjectURL(new Blob(chunks,{type:recorder.mimeType}));localVideoClips.set(id,url);if(!dialog.open||request!==activeVideoRequest)return;canvas.hidden=true;video.hidden=false;video.src=url;status.textContent="";video.play().catch(()=>{})};recorder.start();const start=performance.now();const animate=now=>{drawVideoFrame(ctx,item.variant,Math.min(1,(now-start)/4000));if(now-start<4000&&dialog.open&&request===activeVideoRequest)requestAnimationFrame(animate);else if(recorder.state!=="inactive")recorder.stop()};requestAnimationFrame(animate)}

